-- Light RP vehicle liveries (DRAFT): which TwinTone profile record is which design on which
-- model. The records themselves come from this resource's preload_mod (TweakXL). Painting a
-- car is a server decision (D1): Open77.vehicles.setPaintProfile(vehicleId, record) with a
-- record from THIS table only, never a record name sent by a client.
-- Generated by scripts/vehicle-kit/liveries/build-liveries.ps1 from liveries/lua/liveries_main.lua.
local TAG = '[@@RESOURCE@@]'
local designs, byRecord, byProfile = {}, {}, {}
local count = 0
for _, design in ipairs(LightRpVehicleLiveries.designs) do designs[design.id] = design end
-- `records` = the trims of the model's body that take the same templates (lv_plan.py), primary first.
local function recordsOf(model)
    return type(model.records) == 'table' and model.records or { model.record }
end

for _, model in ipairs(LightRpVehicleLiveries.models) do
    assert(recordsOf(model)[1] == model.record, 'records must start with record on ' .. model.key)
    for _, record in ipairs(recordsOf(model)) do byRecord[record] = model end
    for design, record in pairs(model.profiles) do
        byProfile[record] = { model = model, design = design }
        count = count + 1
    end
end

-- A performance stage or engine sound record (Vehicle.<dealer record>_o77sN, _o77aK,
-- _o77sNaK) shares its model's colour templates, so it takes the same liveries.
local function modelOf(record)
    if type(record) ~= 'string' then return nil end
    return byRecord[record] or byRecord[(record:gsub('_o77s%d+a%d+$', ''):gsub('_o77a%d+$', ''):gsub('_o77s%d+$', ''))]
end

-- liveryProfile(record, design) -> profile record | nil, reason
exports('liveryProfile', function(record, design)
    local model = modelOf(record)
    if not model then return nil, 'unsupported_model' end
    local profile = model.profiles[design]
    if not profile then return nil, 'unknown_design' end
    return profile
end)

-- liveryOf(profile record) -> model key, design id | nil, reason
exports('liveryOf', function(profile)
    local entry = byProfile[profile]
    if not entry then return nil, 'unknown_profile' end
    return entry.model.key, entry.design
end)

-- liveries(record?) -> { { id, label, group, job } ... }: every design, or those the record takes.
exports('liveries', function(record)
    local model = record and modelOf(record)
    if record and not model then return {} end
    local out = {}
    for _, design in ipairs(LightRpVehicleLiveries.designs) do
        if not model or model.profiles[design.id] then
            out[#out + 1] = { id = design.id, label = design.label, group = design.group, job = design.job }
        end
    end
    return out
end)

-- The server only accepts profiles its own catalogue lists (VehicleCustomizationService.
-- TryProfile). Until it can learn pack profiles, setPaintProfile answers invalid_profile
-- for these records: say so once at start instead of failing silently later.
local function probeServer()
    if type(Open77.vehicles.registerPaintProfiles) == 'function' then
        -- `decals` = the template's customDecals count, for the per-car budget of 12 (livery and
        -- stickers together, wave 2). A server that predates the field refuses the row by its
        -- name: register again without it rather than lose every livery.
        local function catalogue(withDecals)
            local out = {}
            for _, model in ipairs(LightRpVehicleLiveries.models) do
                local rows = {}
                for _, design in ipairs(LightRpVehicleLiveries.designs) do
                    local id = model.profiles[design.id]
                    if id then
                        local row = { id = id, label = design.label, main = design.main, sec = design.sec, pattern = true }
                        if withDecals then row.decals = model.decals and model.decals[design.id] or 0 end
                        rows[#rows + 1] = row
                    end
                end
                for _, record in ipairs(recordsOf(model)) do out[record] = rows end
            end
            return out
        end
        local ok, why = Open77.vehicles.registerPaintProfiles(catalogue(true))
        if not ok and tostring(why):find('.decals', 1, true) then
            print(('%s registerPaintProfiles refused the decals field (%s): registering without it, so the '
                .. 'server cannot count liveries in the decal budget'):format(TAG, tostring(why)))
            ok, why = Open77.vehicles.registerPaintProfiles(catalogue(false))
        end
        print(('%s registerPaintProfiles: %s %s'):format(TAG, tostring(ok), tostring(why or '')))
        return
    end
    local listed, total = 0, 0
    for _, model in ipairs(LightRpVehicleLiveries.models) do
        local known = {}
        for _, p in ipairs(Open77.vehicles.listPaintProfiles(model.record) or {}) do known[p.id] = true end
        for _, record in pairs(model.profiles) do
            total = total + 1
            if known[record] then listed = listed + 1 end
        end
    end
    if listed < total then
        print(('%s the server lists %d of %d livery profiles: setPaintProfile refuses the others '
            .. '(invalid_profile) until the server catalogue learns them (scripts/vehicle-kit/docs/liveries.md)')
            :format(TAG, listed, total))
    end
end

local function reply(player, raw, ok, text)
    print(TAG .. ' ' .. text)
    if player and player > 0 then TriggerClientEvent('open77:command:result', player, raw or '', ok == true, text) end
    return ok
end

local function vehicleFor(player, explicit)
    if explicit then
        local id = tonumber(explicit)
        if id and Open77.vehicles.get(id) then return id end
        return nil, 'no vehicle ' .. tostring(explicit)
    end
    local seat = Open77.vehicles.getPlayerSeat(player)
    if seat and seat.vehicleId and Open77.vehicles.get(seat.vehicleId) then return seat.vehicleId end
    return nil, 'sit in a car or pass its id'
end

-- Lab command (restricted, server ACL command.livery): /livery list|off|<design> [vehicleId]
RegisterCommand('livery', function(player, args, raw)
    local verb = args[1] or 'list'
    local vehicle, why = vehicleFor(player, args[2])
    if not vehicle then return reply(player, raw, false, why) end
    local record = Open77.vehicles.get(vehicle).record
    local model = modelOf(record)
    if verb == 'list' then
        local profiles, reason = Open77.vehicles.listPaintProfiles(vehicle)
        if not profiles then return reply(player, raw, false, 'listPaintProfiles: ' .. tostring(reason)) end
        local ours = 0
        for _, p in ipairs(profiles) do if byProfile[p.id] then ours = ours + 1 end end
        local names = {}
        for _, d in ipairs(LightRpVehicleLiveries.designs) do
            if model and model.profiles[d.id] then names[#names + 1] = d.id end
        end
        return reply(player, raw, true, ('%s: server lists %d profiles (%d liveries); designs: %s'):format(
            record, #profiles, ours, model and table.concat(names, ' ') or 'none (unsupported model)'))
    end
    if verb == 'off' then
        local ok, reason = Open77.vehicles.setPaintProfile(vehicle, nil)
        return reply(player, raw, ok, ok and 'livery removed' or ('setPaintProfile: ' .. tostring(reason)))
    end
    if not model then return reply(player, raw, false, record .. ' takes no livery') end
    local profile = model.profiles[verb]
    if not profile then return reply(player, raw, false, 'unknown design ' .. verb) end
    local ok, reason = Open77.vehicles.setPaintProfile(vehicle, profile)
    return reply(player, raw, ok, ok and ('livery ' .. verb .. ' -> ' .. profile)
        or ('setPaintProfile ' .. profile .. ': ' .. tostring(reason)))
end, true)

AddEventHandler('onResourceStart', function(resource)
    if resource ~= GetCurrentResourceName() then return end
    print(('%s %d models, %d livery records (revision %s)'):format(
        TAG, #LightRpVehicleLiveries.models, count, LightRpVehicleLiveries.revision))
    probeServer()
end)
